import type { Word } from "../types";

// Original teaching material. Rows contain: headword | definition | model sentence |
// collocations | usage guidance | retrieval sentence | inflected answer | level.
// Model sentences are invented analytical examples, not quotations from set texts.
type Level = Word["level"];
function unpack(
  source: string,
  category: Word["category"],
  partOfSpeech: Word["partOfSpeech"],
): Word[] {
  return source
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [
        word,
        definition,
        example,
        combinations,
        caution,
        gap,
        answer,
        level = "Developing",
      ] = line.split("|");
      return {
        id: word.toLowerCase().replace(/[^a-z0-9]+/g, "-"),
        word,
        partOfSpeech: word.includes(" ") ? "phrase" : partOfSpeech,
        category,
        level: level as Level,
        definition,
        example,
        collocations: combinations.split(";"),
        caution,
        gap,
        answer,
      };
    });
}
